import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static int[] head, to, next;
    static int edgeCount;

    static void addEdge(int u, int v) {
        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;
    }

    static int bfs(int start, int[] dist, int[] parent) {
        Arrays.fill(dist, -1);
        int[] queue = new int[n];
        int front = 0, back = 0;
        queue[back++] = start;
        dist[start] = 0;
        if (parent != null) parent[start] = -1;

        int farthest = start;
        while (front < back) {
            int u = queue[front++];
            if (dist[u] > dist[farthest]) farthest = u;

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    if (parent != null) parent[v] = u;
                    queue[back++] = v;
                }
            }
        }
        return farthest;
    }

    static int countAtDepth(int start, int blocked, int target,
                            int[] stackNode, int[] stackParent, int[] stackDepth) {
        int top = 0;
        stackNode[top] = start;
        stackParent[top] = blocked;
        stackDepth[top++] = 0;

        int count = 0;
        while (top > 0) {
            int i = --top;
            int u = stackNode[i];
            int p = stackParent[i];
            int depth = stackDepth[i];

            if (depth == target) {
                count++;
                continue;
            }

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (v != p) {
                    stackNode[top] = v;
                    stackParent[top] = u;
                    stackDepth[top++] = depth + 1;
                }
            }
        }
        return count;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();

        head = new int[n];
        Arrays.fill(head, -1);
        to = new int[2 * (n - 1)];
        next = new int[2 * (n - 1)];

        for (int i = 0; i < n - 1; i++) {
            int x = fs.nextInt() - 1;
            int y = fs.nextInt() - 1;
            addEdge(x, y);
            addEdge(y, x);
        }

        int[] dist = new int[n];
        int endpointA = bfs(0, dist, null);
        int[] parent = new int[n];
        int endpointB = bfs(endpointA, dist, parent);
        int diameter = dist[endpointB];

        int[] path = new int[diameter + 1];
        int cur = endpointB;
        for (int i = diameter; i >= 0; i--) {
            path[i] = cur;
            if (i > 0) cur = parent[cur];
        }

        int[] stackNode = new int[n];
        int[] stackParent = new int[n];
        int[] stackDepth = new int[n];
        long ways;

        if (diameter % 2 == 0) {
            int radius = diameter / 2;
            int center = path[radius];
            long total = 0;
            long sameBranchPairs = 0;

            for (int e = head[center]; e != -1; e = next[e]) {
                int count = countAtDepth(to[e], center, radius - 1,
                                         stackNode, stackParent, stackDepth);
                total += count;
                sameBranchPairs += (long) count * count;
            }
            ways = (total * total - sameBranchPairs) / 2;
        } else {
            int radius = diameter / 2;
            int center1 = path[radius];
            int center2 = path[radius + 1];

            long left = countAtDepth(center1, center2, radius,
                                     stackNode, stackParent, stackDepth);
            long right = countAtDepth(center2, center1, radius,
                                      stackNode, stackParent, stackDepth);
            ways = left * right;
        }

        System.out.println(diameter + 1);
        System.out.println(ways);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}
